#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
EnergieBerater KI - Desktop App
Starten: EnergieBerater.exe  (oder python energie_berater_desktop.py)
Daten:   ./EnergieBerater_Daten/
Log:     ./EnergieBerater_Daten/app.log
"""

import sys, os, json, uuid, threading, time, mimetypes, traceback
import urllib.request, urllib.error, urllib.parse
from pathlib import Path
from http.server import HTTPServer, BaseHTTPRequestHandler

PORT = 8080

# ── Pfade (funktioniert als .py und als .exe) ─────────────────────────────────
if getattr(sys, "frozen", False):
    APP_DIR = Path(sys.executable).parent
else:
    APP_DIR = Path(__file__).parent

BASE_DIR   = APP_DIR / "EnergieBerater_Daten"
FILES_DIR  = BASE_DIR / "dateien"
STORE_FILE = BASE_DIR / "store.json"
LOCK_FILE  = BASE_DIR / ".store.lock"
CONFIG_FILE = BASE_DIR / "config.json"
LOG_FILE   = BASE_DIR / "app.log"

# ── Logging ───────────────────────────────────────────────────────────────────
import logging
def setup_logging():
    BASE_DIR.mkdir(parents=True, exist_ok=True)
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s %(levelname)s %(message)s",
        handlers=[
            logging.FileHandler(LOG_FILE, encoding="utf-8"),
            logging.StreamHandler(sys.stdout),
        ]
    )
setup_logging()
log = logging.getLogger("eb")

# ── Verzeichnisse anlegen ─────────────────────────────────────────────────────
def init_dirs():
    BASE_DIR.mkdir(parents=True, exist_ok=True)
    FILES_DIR.mkdir(parents=True, exist_ok=True)
    if not STORE_FILE.exists():
        STORE_FILE.write_text("{}", encoding="utf-8")
    if not CONFIG_FILE.exists():
        CONFIG_FILE.write_text("{}", encoding="utf-8")
    # Alten Lock aufräumen
    try:
        if LOCK_FILE.exists() and (time.time() - LOCK_FILE.stat().st_mtime) > 30:
            LOCK_FILE.unlink(missing_ok=True)
    except Exception:
        pass
    log.info(f"Daten-Ordner: {BASE_DIR}")

# ── Datei-Lock für OneDrive-Sicherheit ───────────────────────────────────────
_mem_lock = threading.Lock()

class _FileLock:
    def __init__(self, path, timeout=8.0):
        self.path = path
        self.timeout = timeout
    def __enter__(self):
        deadline = time.time() + self.timeout
        while time.time() < deadline:
            try:
                fd = os.open(str(self.path), os.O_CREAT | os.O_EXCL | os.O_WRONLY)
                os.write(fd, str(os.getpid()).encode())
                os.close(fd)
                return self
            except FileExistsError:
                try:
                    if time.time() - self.path.stat().st_mtime > 15:
                        self.path.unlink(missing_ok=True)
                        continue
                except Exception:
                    pass
                time.sleep(0.08)
        return self
    def __exit__(self, *_):
        try:
            self.path.unlink(missing_ok=True)
        except Exception:
            pass

def _with_store(fn):
    with _mem_lock:
        with _FileLock(LOCK_FILE):
            try:
                raw = STORE_FILE.read_text(encoding="utf-8") if STORE_FILE.exists() else "{}"
                data = json.loads(raw)
            except Exception:
                data = {}
            result = fn(data)
            try:
                tmp = STORE_FILE.with_suffix(".tmp")
                tmp.write_text(json.dumps(data, ensure_ascii=False), encoding="utf-8")
                tmp.replace(STORE_FILE)
            except Exception as e:
                log.error(f"Store-Schreibfehler: {e}")
            return result

def store_get(key):
    return _with_store(lambda d: d.get(key))

def store_set(key, value):
    _with_store(lambda d: d.update({key: value}))
    return True

def store_delete(key):
    _with_store(lambda d: d.pop(key, None))

# ── Config (API-Key etc.) ─────────────────────────────────────────────────────
_cfg_lock = threading.Lock()
CONFIG_LOCK_FILE = BASE_DIR / ".config.lock"

def config_get(key):
    with _cfg_lock:
        with _FileLock(CONFIG_LOCK_FILE):
            try:
                return json.loads(CONFIG_FILE.read_text(encoding="utf-8")).get(key)
            except Exception:
                return None

def config_set(key, value):
    with _cfg_lock:
        with _FileLock(CONFIG_LOCK_FILE):
            try:
                data = json.loads(CONFIG_FILE.read_text(encoding="utf-8")) if CONFIG_FILE.exists() else {}
                data[key] = value
                tmp = CONFIG_FILE.with_suffix(".tmp")
                tmp.write_text(json.dumps(data, ensure_ascii=False), encoding="utf-8")
                tmp.replace(CONFIG_FILE)
            except Exception as e:
                log.error(f"Config-Fehler: {e}")





# ── HTTP Handler ──────────────────────────────────────────────────────────────
class Handler(BaseHTTPRequestHandler):

    def do_GET(self):
        path = self.path.split("?")[0]

        # App HTML
        if path in ("/", "/index.html"):
            body = HTML_CONTENT.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            # Allow eval() for Babel JSX transformation
            self.send_header("Content-Security-Policy",
                "default-src * 'unsafe-inline' 'unsafe-eval' data: blob:;")
            self.end_headers()
            self.wfile.write(body)

        # Key-Value lesen
        elif path.startswith("/data/"):
            key = urllib.parse.unquote(path[6:])
            if not key:
                self._json(400, {"error": "Kein Key"}); return
            val = store_get(key)
            if val is None:
                self.send_response(404); self._cors(); self.end_headers()
            else:
                self._json(200, val)


        # Datei laden
        elif path.startswith("/files/"):
            file_id = path[7:]
            file_path = FILES_DIR / file_id
            if not file_path.exists() or not file_path.is_file():
                self.send_response(404); self._cors(); self.end_headers(); return
            mime = mimetypes.guess_type(str(file_path))[0] or "application/octet-stream"
            data = file_path.read_bytes()
            self.send_response(200)
            self.send_header("Content-Type", mime)
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "max-age=86400")
            self._cors(); self.end_headers(); self.wfile.write(data)

        # Config / Mode lesen
        elif path == "/config/mode":
            if self.command == "GET":
                self._json(200, {
                    "mode":           "ollama",
                    "ollama_model":   config_get("ollama_model") or "llama3.2",
                    "ollama_url":     config_get("ollama_url") or "http://localhost:11434",
                    "ollama_apikey":  config_get("ollama_apikey") or "",
                }, no_cache=True)
            elif self.command == "POST":
                body2 = self.rfile.read(int(self.headers.get("Content-Length",0)))
                data2 = json.loads(body2)
                for k in ("ollama_model","ollama_url","ollama_apikey"):
                    if k in data2: config_set(k, data2[k])
                self._json(200, {"ok": True})

        # Ollama Verbindungstest + Modell-Liste
        elif path == "/config/ollama_test":
            url = config_get("ollama_url") or "http://localhost:11434"
            try:
                hdrs = {"User-Agent": "EnergieBerater/1.0"}
                ak = config_get("ollama_apikey")
                if ak: hdrs["Authorization"] = f"Bearer {ak}"
                req = urllib.request.Request(f"{url}/api/tags", headers=hdrs)
                with urllib.request.urlopen(req, timeout=5) as r:
                    data3 = json.loads(r.read())
                models = [m["name"] for m in data3.get("models",[])]
                self._json(200, {"ok": True, "models": models})
            except Exception as e:
                self._json(200, {"ok": False, "error": str(e)})

        else:
            self.send_response(404); self._cors(); self.end_headers()

    def do_OPTIONS(self):
        self.send_response(200); self._cors(); self.end_headers()

    def do_DELETE(self):
        path = self.path.split("?")[0]
        if path.startswith("/data/"):
            key = urllib.parse.unquote(path[6:])
            store_delete(key)
            self._json(200, {"ok": True})
        elif path.startswith("/files/"):
            file_id = path[7:]
            fp = FILES_DIR / file_id
            if fp.exists():
                fp.unlink()
            self._json(200, {"ok": True})
        else:
            self.send_response(404); self._cors(); self.end_headers()

    def do_POST(self):
        path = self.path.split("?")[0]
        length = int(self.headers.get("Content-Length", 0))

        # Key-Value speichern
        if path.startswith("/data/"):
            key = urllib.parse.unquote(path[6:])
            body = self.rfile.read(length)
            try:
                value = json.loads(body)
                store_set(key, value)
                self._json(200, {"ok": True})
            except json.JSONDecodeError as e:
                self._json(400, {"error": f"JSON-Fehler: {e}"})

        # Datei hochladen
        elif path == "/files":
            content_type = self.headers.get("Content-Type", "application/octet-stream").split(";")[0].strip()
            raw_name = self.headers.get("X-File-Name", "datei.bin")
            orig_name = urllib.parse.unquote(raw_name)
            ext = Path(orig_name).suffix.lower()
            if not ext:
                ext = {
                    "application/pdf": ".pdf",
                    "image/jpeg": ".jpg", "image/png": ".png", "image/webp": ".webp",
                }.get(content_type, ".bin")
            file_id = str(uuid.uuid4()) + ext
            data = self.rfile.read(length)
            (FILES_DIR / file_id).write_bytes(data)
            log.info(f"Datei gespeichert: {file_id} ({len(data):,} B) <- {orig_name}")
            self._json(200, {"fileId": file_id, "origName": orig_name, "size": len(data)})

        # API Proxy → Ollama
        elif path == "/api":
            body = self.rfile.read(length)
            ollama_model  = config_get("ollama_model")  or "llama3.2"
            ollama_url    = config_get("ollama_url")    or "http://localhost:11434"
            ollama_apikey = config_get("ollama_apikey") or ""
            try:
                payload = json.loads(body)
                messages = payload.get("messages", [])
                system   = payload.get("system", "")
                ollama_msgs = []
                if system:
                    ollama_msgs.append({"role": "system", "content": system})
                for m in messages:
                    content = m.get("content", "")
                    if isinstance(content, list):
                        # Multimodal: nur Text extrahieren
                        text_parts = [c.get("text","") for c in content if c.get("type")=="text"]
                        content = " ".join(text_parts)
                    ollama_msgs.append({"role": m["role"], "content": content})
                ollama_payload = json.dumps({
                    "model":    ollama_model,
                    "messages": ollama_msgs,
                    "stream":   False,
                    "options":  {"num_predict": payload.get("max_tokens", 2000)}
                }).encode()
                ollama_headers = {"Content-Type": "application/json"}
                if ollama_apikey: ollama_headers["Authorization"] = f"Bearer {ollama_apikey}"
                req = urllib.request.Request(
                    f"{ollama_url}/api/chat",
                    data=ollama_payload,
                    headers=ollama_headers)
                with urllib.request.urlopen(req, timeout=300) as resp:
                    resp_data = json.loads(resp.read())
                text = resp_data.get("message", {}).get("content", "")
                result = json.dumps({"content": [{"type": "text", "text": text}]}).encode()
                self.send_response(200)
                self.send_header("Content-Type", "application/json")
                self._cors(); self.end_headers(); self.wfile.write(result)
            except urllib.error.HTTPError as e:
                err_body = ""
                try: err_body = e.read().decode("utf-8", errors="replace")
                except: pass
                if e.code == 404:
                    model_hint = f"Modell '{ollama_model}' nicht gefunden. Bitte ausführen: ollama pull {ollama_model}"
                    self._json(503, {"error": {"message": model_hint}})
                else:
                    self._json(503, {"error": {"message": f"Ollama HTTP {e.code}: {err_body[:200]}"}})
            except urllib.error.URLError as e:
                self._json(503, {"error": {"message": f"Ollama nicht erreichbar. Bitte 'ollama serve' starten. ({e.reason})"}})
            except Exception as e:
                log.error(f"Ollama-Fehler: {e}")
                self._json(500, {"error": {"message": str(e)}})
        else:
            self.send_response(404); self._cors(); self.end_headers()

    def _json(self, code, obj, no_cache=False):
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        if no_cache:
            self.send_header("Cache-Control", "no-store, no-cache, must-revalidate")
            self.send_header("Pragma", "no-cache")
        self._cors(); self.end_headers(); self.wfile.write(body)

    def _cors(self):
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, DELETE, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type, X-Api-Key, X-File-Name")

    def log_message(self, fmt, *args):
        msg = fmt % args
        if "200" not in msg and "OPTIONS" not in msg:
            log.debug(f"HTTP: {msg}")


# ── Eingebettetes HTML ────────────────────────────────────────────────────────

APP_ICON_B64 = ""

_APP_JSX_B64 = ""
import base64 as _base64

# Platzhalter – wird von build_setup.py durch gebundelte HTML (offline) ersetzt
_HTML_B64 = "<!--HTML_B64_PLACEHOLDER-->"

def _build_html_dev():
    """Fallback für direkten Python-Start (python energie_berater_app.py).
    Nutzt CDN – identische Versionen wie build_setup.py."""
    jsx = _base64.b64decode(_APP_JSX_B64).decode("utf-8")
    CDN = "https://cdnjs.cloudflare.com/ajax/libs"
    return "\n".join([
        "<!DOCTYPE html>",
        '<html lang="de"><head>',
        '<meta charset="UTF-8">',
        "<title>EnergieBerater KI</title>",
        f'<script src="{CDN}/react/18.2.0/umd/react.production.min.js"></script>',
        f'<script src="{CDN}/react-dom/18.2.0/umd/react-dom.production.min.js"></script>',
        f'<script src="{CDN}/babel-standalone/7.23.2/babel.min.js"></script>',
        "<style>*{box-sizing:border-box;margin:0;padding:0}",
        "html,body,#root{height:100%;overflow:hidden}",
        "body{background:#0e1118}</style>",
        "</head><body>",
        '<div id="root" style="height:100%"></div>',
        '<script type="text/babel" data-presets="react">',
        jsx,
        "</script></body></html>",
    ])

# Patch-Datei neben der EXE hat höchste Priorität (erzeugt von patch.py)
_patch_file = Path(sys.executable).parent / "html_patch.b64" if getattr(sys, "frozen", False) else None
if _patch_file and _patch_file.exists():
    HTML_CONTENT = _base64.b64decode(_patch_file.read_bytes()).decode("utf-8")
elif _HTML_B64.startswith("<!--"):
    HTML_CONTENT = _build_html_dev()
else:
    HTML_CONTENT = _base64.b64decode(_HTML_B64).decode("utf-8")


if __name__ == "__main__":
    try:
        init_dirs()

        # Port finden und Server starten
        port = PORT
        for _ in range(10):
            try:
                srv = HTTPServer(("localhost", port), Handler)
                break
            except OSError:
                port += 1

        url = f"http://localhost:{port}"
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        time.sleep(0.4)
        log.info(f"Server: {url}  Daten: {BASE_DIR}")

        # PyQt6 Desktop-Fenster
        from PyQt6.QtWidgets import QApplication, QMainWindow
        from PyQt6.QtWebEngineWidgets import QWebEngineView
        from PyQt6.QtWebEngineCore import QWebEngineProfile, QWebEngineSettings, QWebEnginePage
        from PyQt6.QtCore import QUrl

        qt = QApplication(sys.argv)
        qt.setApplicationName("EnergieBerater KI")

        profile = QWebEngineProfile("EnergieBerater", qt)
        profile.setPersistentStoragePath(str(BASE_DIR / "qt_storage"))
        profile.setCachePath(str(BASE_DIR / "qt_cache"))
        s = profile.settings()
        for attr in [
            QWebEngineSettings.WebAttribute.LocalStorageEnabled,
            QWebEngineSettings.WebAttribute.JavascriptEnabled,
            QWebEngineSettings.WebAttribute.LocalContentCanAccessRemoteUrls,
            QWebEngineSettings.WebAttribute.AllowRunningInsecureContent,
            QWebEngineSettings.WebAttribute.JavascriptCanOpenWindows,
            QWebEngineSettings.WebAttribute.JavascriptCanAccessClipboard,
        ]:
            try:
                s.setAttribute(attr, True)
            except Exception:
                pass
        # Chromium flags: allow eval, disable web security for localhost
        os.environ.setdefault("QTWEBENGINE_CHROMIUM_FLAGS",
            "--disable-web-security --allow-running-insecure-content "
            "--disable-features=BlockInsecurePrivateNetworkRequests")

        _cleaned = [False]

        class DebugPage(QWebEnginePage):
            def javaScriptConsoleMessage(self, level, message, line, source):
                log.info(f"JS [{level.name}] {source}:{line}: {message}")

        class MainWindow(QMainWindow):
            def closeEvent(self, event):
                if not _cleaned[0]:
                    _cleaned[0] = True
                    try:
                        view.stop()
                        view.setPage(None)
                        page.deleteLater()
                        view.deleteLater()
                        profile.deleteLater()
                    except Exception:
                        pass
                event.accept()
                qt.quit()

        win = MainWindow()
        win.setWindowTitle("EnergieBerater KI")
        win.resize(1440, 920)
        win.setMinimumSize(960, 640)
        # Icon setzen falls vorhanden
        try:
            from PyQt6.QtGui import QIcon
            import base64, tempfile
            icon_data = base64.b64decode(APP_ICON_B64)
            tmp_ico = Path(tempfile.mktemp(suffix=".ico"))
            tmp_ico.write_bytes(icon_data)
            win.setWindowIcon(QIcon(str(tmp_ico)))
            qt.setWindowIcon(QIcon(str(tmp_ico)))
        except Exception as e:
            log.warning(f"Icon konnte nicht gesetzt werden: {e}")

        page = DebugPage(profile, win)
        view = QWebEngineView(win)
        view.setPage(page)
        win.setCentralWidget(view)
        win.show()
        page.load(QUrl(url + "/"))

        qt.exec()
        os._exit(0)

    except Exception as e:
        log.error(f"Fehler: {e}")
        import traceback; log.error(traceback.format_exc())
        try:
            import ctypes
            ctypes.windll.user32.MessageBoxW(0,
                f"Fehler beim Starten:\n\n{e}\n\nLog: {LOG_FILE}",
                "EnergieBerater KI", 0x10)
        except Exception:
            input(f"Fehler: {e}\nEnter...")
    finally:
        try: srv.shutdown()
        except Exception: pass
